import type { Metadata } from 'next'
import type { ReactNode } from 'react'
import Link from 'next/link'
import { SiteHeader } from '@/components/SiteHeader'
import { getCourses } from '@/lib/queries'
import { isUnbookable } from '@/data/course-status'

// Landing page for the printable map ("algarve golf courses map pdf").
// The PDF and preview are generated by scripts/build-map-pdf.mjs into
// public/downloads/. Re-run it when courses change, then update PDF_UPDATED.

const BASE = 'https://www.algarvegolfmap.com'
const PAGE_URL = `${BASE}/algarve-golf-courses-map-pdf`
const PDF = '/downloads/algarve-golf-courses-map.pdf'
const PREVIEW = '/downloads/algarve-golf-courses-map-preview.jpg'
const PDF_UPDATED = '16 November 2026'
const PDF_SIZE = '0.4 MB'

const H1 = 'Algarve golf courses map (PDF)'
const SEO_TITLE = 'Algarve golf courses map PDF: free printable map'

export const revalidate = 86400

export async function generateMetadata(): Promise<Metadata> {
  const courses = await getCourses()
  const description = `Free printable map of every golf course in the Algarve: ${courses.length + 1} courses numbered west to east, Faro Airport and main towns, on one A4 page. Download the PDF.`
  return {
    title: { absolute: SEO_TITLE },
    description,
    alternates: { canonical: PAGE_URL },
    openGraph: {
      title: SEO_TITLE, description, url: PAGE_URL,
      siteName: 'Algarve Golf Map', locale: 'en_GB', type: 'website',
      images: [{ url: `${BASE}${PREVIEW}`, width: 1684, height: 1191, alt: 'Printable map of Algarve golf courses' }],
    },
  }
}

const link = { color: '#2B6090', textDecoration: 'none', fontWeight: 500 } as const
function A({ href, children }: { href: string; children: ReactNode }) {
  return <Link href={href} style={link}>{children}</Link>
}

export default async function MapPdfPage() {
  const courses = await getCourses()
  // getCourses() leaves out the private Els Club, which the PDF includes.
  const total = courses.length + 1
  const open = courses.filter(c => !isUnbookable(c.slug)).length

  const downloadBtn = (source: string) => (
    <a
      href={PDF}
      download
      data-download-click="algarve-golf-courses-map.pdf"
      data-download-source={source}
      style={{
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 8,
        minHeight: 50, padding: '0 24px', borderRadius: 12,
        background: '#2B6090', color: '#fff', fontSize: 16, fontWeight: 700, textDecoration: 'none',
        boxShadow: '0 2px 8px rgba(43,96,144,.25)',
      }}
    >
      Download the PDF (free)
    </a>
  )

  const breadcrumbLd = {
    '@context': 'https://schema.org',
    '@type': 'BreadcrumbList',
    itemListElement: [
      { '@type': 'ListItem', position: 1, name: 'Home', item: BASE },
      { '@type': 'ListItem', position: 2, name: 'All golf courses', item: `${BASE}/courses` },
      { '@type': 'ListItem', position: 3, name: H1, item: PAGE_URL },
    ],
  }

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbLd) }} />
      <div style={{ minHeight: '100vh', background: '#f9f9f9', fontFamily: 'var(--font-body)' }}>
        <SiteHeader showBackToMap />

        <div style={{ maxWidth: 860, margin: '0 auto', padding: '14px 24px 80px' }}>
          <nav aria-label="Breadcrumb">
            <ol style={{ display: 'flex', flexWrap: 'wrap', gap: '4px 8px', listStyle: 'none', padding: 0, margin: 0, fontSize: 13, color: '#6a6a6a' }}>
              <li><Link href="/" style={{ color: '#6a6a6a', textDecoration: 'none' }}>Home</Link></li>
              <li aria-hidden="true">›</li>
              <li><Link href="/courses" style={{ color: '#6a6a6a', textDecoration: 'none' }}>All golf courses</Link></li>
              <li aria-hidden="true">›</li>
              <li aria-current="page" style={{ color: '#222', fontWeight: 600 }}>Map PDF</li>
            </ol>
          </nav>

          <h1 style={{ fontSize: 34, fontWeight: 800, color: '#222', lineHeight: 1.15, margin: '22px 0 12px' }}>{H1}</h1>
          <p style={{ fontSize: 17, lineHeight: 1.65, color: '#333', margin: '0 0 18px', maxWidth: 700 }}>
            A free, printable map of every golf course in the Algarve on one A4 page. All {total} courses
            are numbered from west to east, from Santo António near Sagres to Quinta do Vale on the Spanish
            border, with Faro Airport and the main towns marked so you can see where to stay.
          </p>

          <div style={{ display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap', marginBottom: 22 }}>
            {downloadBtn('top')}
            <span style={{ fontSize: 13.5, color: '#6a6a6a' }}>PDF · A4 landscape · {PDF_SIZE} · updated {PDF_UPDATED}</span>
          </div>

          <a href={PDF} download data-download-click="algarve-golf-courses-map.pdf" data-download-source="preview" style={{ display: 'block' }}>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img
              src={PREVIEW}
              alt="Preview of the printable Algarve golf courses map, with numbered courses, towns and Faro Airport"
              width={1684}
              height={1191}
              style={{ width: '100%', height: 'auto', display: 'block', borderRadius: 14, border: '1px solid #e4e4e4', boxShadow: '0 4px 24px rgba(0,0,0,.08)', background: '#fff' }}
            />
          </a>

          <section style={{ marginTop: 30, fontSize: 15.5, lineHeight: 1.7, color: '#444' }}>
            <h2 style={{ fontSize: 20, fontWeight: 800, color: '#222', margin: '0 0 8px' }}>What is on the map</h2>
            <ul style={{ margin: 0, paddingLeft: 20, listStyle: 'disc' }}>
              <li>All {total} golf courses, colour-coded by area: western, central and eastern Algarve.</li>
              <li>A key with each course&apos;s name, number of holes and nearest town.</li>
              <li>Faro Airport and the main towns, from Sagres and Lagos to Tavira and Castro Marim.</li>
              <li>
                Which courses visitors can&apos;t play: {total - open === 2 ? 'San Lorenzo is closed for renovation until mid-2028 and The Els Club is a private members club' : 'closed and private courses are shown in grey'}.
              </li>
              <li>A QR code that opens the <A href="/">interactive map</A>, with green fees and tee times for every course.</li>
            </ul>
          </section>

          <section style={{ marginTop: 26, fontSize: 15.5, lineHeight: 1.7, color: '#444' }}>
            <h2 style={{ fontSize: 20, fontWeight: 800, color: '#222', margin: '0 0 8px' }}>Need more than a printed map?</h2>
            <p style={{ margin: '0 0 12px' }}>
              The <A href="/">interactive Algarve golf map</A> shows every course with drive times from Faro
              Airport, nearby hotels and green fees. For a side-by-side table with par and prices, see the{' '}
              <A href="/courses">full list of Algarve golf courses</A>.
            </p>
            {downloadBtn('bottom')}
          </section>

          <p style={{ fontSize: 12.5, color: '#767676', marginTop: 28 }}>
            Course positions are approximate (clubhouse location). Map data © Mapbox © OpenStreetMap contributors.
            You are welcome to print and share the map for personal use.
          </p>
        </div>
      </div>
    </>
  )
}
